import * as React from "react";
import { motion } from "framer-motion";
import { Link, Element, animateScroll as scroll } from "react-scroll";

const variants = {
	open: {
		y: 0,
		opacity: 1,
		transition: {
			y: { stiffness: 1000, velocity: -100 },
		},
	},
	closed: {
		y: 50,
		opacity: 0,
		transition: {
			y: { stiffness: 1000 },
		},
	},
};

const colors = ["#FF008C", "#D309E1", "#9C1AFF", "#7700FF", "#5500ff"];
const link = ["Home", "About", "Skill", "Site", "Project"];
const to = ["home", "about", "skill", "site-box", "project-box"];
const activeClass = ["active", "active", "active", "active", "active"];
const spy = [true, true, true, true, true];
const smooth = [true, true, true, true, true];
const offset = [0, 0, 0, 0, 0];
const duration = [500, 500, 500, 500, 500];

export const MenuItem = ({ i }) => {
	const style = { border: `2px solid ${colors[i]}` };
	const fontStyle = { color: colors[i], fontSize: `24px` };
	return (
		<div>
			<motion.li variants={variants} whileHover={{ scale: 1.1 }} whileTap={{ scale: 0.95 }}>
				{/* <div className="icon-placeholder" style={style}></div> */}
				{/* <div className="text-placeholder" style={style}></div> */}
				<Link style={fontStyle} to={to[i]} activeClass={activeClass[i]} spy={spy[i]} smooth={smooth[i]} offset={offset[i]} duration={duration[i]}>
					{link[i]}
				</Link>
			</motion.li>
		</div>
	);
};
