import { render } from "react-dom";
import { motion, useTime, useTransform } from "framer-motion";
import { animate } from "framer-motion";
import * as React from "react";
import AOS from "aos";
import "aos/dist/aos.css";

function Home() {
	const time = useTime();
	const rotate = useTransform(time, [0, 4000], [0, 360], { clamp: false });

	const draw = {
		hidden: { pathLength: 0, opacity: 0 },
		visible: (i) => {
			const delay = 1 + i * 0.3;
			return {
				pathLength: 1,
				opacity: 1,
				transition: {
					pathLength: { delay, type: "spring", duration: 1.5, bounce: 0 },
					opacity: { delay, duration: 0.5 },
				},
			};
		},
	};

	return (
		<div className="wrap home" name="home">
			<video autoPlay muted loop playsinline>
				<source src="/img/bg-video.mp4" type="video/mp4"></source>
			</video>
			<motion.div className="intro" initial="hidden" animate="visible">
				<motion.h1 className="name" variants={draw} custom={1}>
					- 김정인 -
				</motion.h1>
				<motion.h1 className="txt" variants={draw} custom={2}>
					프론트 엔드 개발자 포트폴리오
				</motion.h1>
				<motion.div className="bar-1" variants={draw} custom={3}></motion.div>
				<motion.p className="hi" variants={draw} custom={4}>
					안녕하세요.
				</motion.p>
				<motion.p variants={draw} custom={5}>
					본연에 집중하는 개발자 김정인입니다.
				</motion.p>
			</motion.div>
		</div>
	);
}

export default Home;
